type GameId = 'lebem' | 'tictactoe' | 'soundhunter' | 'familyquiz' | 'adventure' | 'pixelboard' | 'stopgame' | 'spotit' | 'memory' | 'tapit' | 'jumpparty' | 'drawguess' | 'animalarena' | 'crazykitchen' | 'miniparty' | 'hideseek' | 'buttonmayhem' | 'bombbrawl';

function gameFromHash(): GameId | null {
  const h = window.location.hash.toLowerCase();
  if (h.startsWith('#/leitor') || h.startsWith('#/lebem')) return 'lebem';
  if (h.startsWith('#/tictactoe') || h.startsWith('#/galo')) return 'tictactoe';
  if (h.startsWith('#/soundhunter')) return 'soundhunter';
  if (h.startsWith('#/familyquiz')) return 'familyquiz';
  if (h.startsWith('#/adventure')) return 'adventure';
  if (h.startsWith('#/pixelboard')) return 'pixelboard';
  if (h.startsWith('#/stopgame')) return 'stopgame';
  if (h.startsWith('#/spotit')) return 'spotit';
  if (h.startsWith('#/memory')) return 'memory';
  if (h.startsWith('#/tapit')) return 'tapit';
  if (h.startsWith('#/jumpparty')) return 'jumpparty';
  if (h.startsWith('#/drawguess')) return 'drawguess';
  if (h.startsWith('#/animalarena')) return 'animalarena';
  if (h.startsWith('#/crazykitchen')) return 'crazykitchen';
  if (h.startsWith('#/miniparty')) return 'miniparty';
  if (h.startsWith('#/hideseek')) return 'hideseek';
  if (h.startsWith('#/buttonmayhem')) return 'buttonmayhem';
  if (h.startsWith('#/bombbrawl')) return 'bombbrawl';
  return null;
}

