// ─── Component ───────────────────────────────────────────────────────────────

interface AppProps {
  topBarRight?: React.ReactNode;
  isAuthenticated?: boolean;
}

type Filter = 'all' | 'online' | 'multiplayer' | 'solo';

export default function App({ topBarRight, isAuthenticated = false }: AppProps) {
  const [game, setGame] = useState<GameId | null>(gameFromHash);
  const [filter, setFilter] = useState<Filter>('all');
  const [locale] = useLocale();
  const lang = locale === 'pt' ? 'pt' : 'en';

  // Clear focus when switching between the landing and any game screen.
  // Without this the button that initiated the transition keeps its focus
  // ring visible against the new screen, which looks like a bug.
  useEffect(() => {
    (document.activeElement as HTMLElement | null)?.blur();
  }, [game]);

  useEffect(() => {
    const onHash = () => setGame(gameFromHash());
    window.addEventListener('hashchange', onHash);
    return () => window.removeEventListener('hashchange', onHash);
  }, []);

  // Landing page
  if (!game) {
    return (
      <Layout title={lang === 'pt' ? 'Jogos' : 'Games'} sidebar={null} topBarRight={topBarRight}>
        <LandingWrap>
          {STARS.map((s, i) => (
            <Star key={i} x={s.x} y={s.y} size={s.size} delay={s.delay} dur={s.dur} />
          ))}
          <Comet top={15} delay={12} />
          <Comet top={55} delay={25} />
          <LandingTitle>{lang === 'pt' ? 'Vamos jogar!' : 'Let\u2019s play!'}</LandingTitle>
          <LandingSub>{lang === 'pt' ? 'Escolhe um jogo para começar' : 'Pick a game to get started'}</LandingSub>
          <FilterBar>
            <FilterChip active={filter === 'all'} onClick={() => setFilter('all')}>
              🎮 {lang === 'pt' ? 'Todos' : 'All'}
            </FilterChip>
            <FilterChip active={filter === 'online'} chipColor="#3fb950" onClick={() => setFilter('online')}>
              🌐 Online
            </FilterChip>
            <FilterChip active={filter === 'multiplayer'} chipColor="#d2a8ff" onClick={() => setFilter('multiplayer')}>
              👥 3+ {lang === 'pt' ? 'Jogadores' : 'Players'}
            </FilterChip>
            <FilterChip active={filter === 'solo'} chipColor="#f59e0b" onClick={() => setFilter('solo')}>
              🎯 {lang === 'pt' ? 'Sozinho' : 'Solo'}
            </FilterChip>
          </FilterBar>
          <CardsRow>
            {GAMES
              .filter((g) => {
                if (filter === 'online') return g.online;
                if (filter === 'multiplayer') return g.maxPlayers >= 3;
                if (filter === 'solo') return g.maxPlayers === 1;
                return true;
              })
              .map((g, i) => (
              <SubjectCard
                key={g.id}
                accentColor={g.color}
                onClick={() => {
                  setGame(g.id);
                  window.location.hash = g.hash;
                }}
              >
                {isAuthenticated && g.online && <OnlineBadge>🌐 Online</OnlineBadge>}
                {g.maxPlayers > 1 && <PlayersBadge>👥 {g.maxPlayers === 2 ? '2' : `2-${g.maxPlayers}`}</PlayersBadge>}
                <CardEmoji className="card-emoji" delay={i * 0.4}>{g.emoji}</CardEmoji>
                <CardLabel>{g.label[lang]}</CardLabel>
                <CardDesc>{g.description[lang]}</CardDesc>
              </SubjectCard>
            ))}
          </CardsRow>
        </LandingWrap>
      </Layout>
    );
  }

  // Back button
  const backBar = (
    <TopBarInject>
      <BackBtn onClick={() => { setGame(null); window.location.hash = '#/games'; }}>
        ← {lang === 'pt' ? 'Jogos' : 'Games'}
      </BackBtn>
      {topBarRight}
    </TopBarInject>
  );

  const cfg = GAMES.find((g) => g.id === game)!;
  const goBack = () => { setGame(null); window.location.hash = '#/games'; };

  if (game === 'lebem') {
    return (
      <Layout title="LêBem" sidebar={null} topBarRight={backBar}>
        <LeBemApp onBack={goBack} />
      </Layout>
    );
  }

  const gameComponents: Record<Exclude<GameId, 'lebem'>, React.ReactNode> = {
    tictactoe: <TicTacToe lang={lang} onBack={goBack} canOnline={isAuthenticated} />,
    soundhunter: <SoundHunter lang={lang} onBack={goBack} />,
    familyquiz: <FamilyQuiz lang={lang} onBack={goBack} canOnline={isAuthenticated} />,
    adventure: <TextAdventure lang={lang} onBack={goBack} />,
    pixelboard: <PixelBoard lang={lang} onBack={goBack} />,
    stopgame: <StopGame lang={lang} onBack={goBack} canOnline={isAuthenticated} />,
    spotit: <SpotIt lang={lang} onBack={goBack} canOnline={isAuthenticated} />,
    memory: <MemoryGame lang={lang} onBack={goBack} canOnline={isAuthenticated} />,
    tapit: <TapIt lang={lang} onBack={goBack} canOnline={isAuthenticated} />,
    jumpparty: <JumpParty lang={lang} onBack={goBack} />,
    drawguess: <DrawGuess lang={lang} onBack={goBack} canOnline={isAuthenticated} />,
    animalarena: <AnimalArena lang={lang} onBack={goBack} />,
    crazykitchen: <CrazyKitchen lang={lang} onBack={goBack} />,
    miniparty: <MiniParty lang={lang} onBack={goBack} />,
    hideseek: <HideSeek lang={lang} onBack={goBack} />,
    buttonmayhem: <ButtonMayhem lang={lang} onBack={goBack} />,
    bombbrawl: <BombBrawl lang={lang} onBack={goBack} canOnline={isAuthenticated} />,
  };

  return (
    <Layout title={cfg.title[lang]} sidebar={null} topBarRight={backBar}>
      {gameComponents[game as Exclude<GameId, 'lebem'>]}
    </Layout>
  );
}
